    f=c.makefile('rwb',buffering=0)
    def s(x): f.write((x+'\r\n').encode())
    s('220 fake')
    dsock=None
    while True:
        l=f.readline()
        if not l: break
        l=l.decode(errors='replace').rstrip('\r\n'); LOG.write(l+'\n'); LOG.flush()
        cmd=l.split(' ')[0].upper(); arg=l[len(cmd)+1:]
        if cmd=='FEAT': s('211-Features:'); s(' AUTH TLS'); s(' PASV'); s('211 End')
        elif cmd=='AUTH': s('534 no tls here')
        elif cmd=='USER': s('331 pw')
        elif cmd=='PASS': s('230 ok' if MODE=='ok' else '530 Login incorrect.')
        elif cmd=='PWD': s('257 "/"')
        elif cmd=='CWD': s('250 ok')
