            s('150 here'); d,_=dsock.accept(); d.close(); dsock.close(); s('226 done')
        elif cmd=='SIZE' or cmd=='MDTM': s('550 no')
        elif cmd=='MKD': s('257 created')
        elif cmd=='STOR':
            s('150 go'); d,_=dsock.accept()
            while d.recv(65536): pass
            d.close(); dsock.close(); s('226 done')
        elif cmd=='QUIT': s('221 bye'); break
        else: s('502 nope')
    c.close()
srv=socket.socket(); srv.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); srv.bind(('127.0.0.1',PORT)); srv.listen(5)
srv.settimeout(25)
try:
    while True:
        c,_=srv.accept(); threading.Thread(target=handle,args=(c,),daemon=True).start()
except socket.timeout: pass
